import React from "react";
import { Link } from "react-router-dom";
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, PieChart, Pie, Cell } from "recharts";
import { Target, Trophy, BookOpen, ArrowRight, TrendingUp } from "lucide-react";
import { questions } from "../data/questions";

export default function Progress() {
  const completed = Number(localStorage.getItem("prepai-completed") || 0);
  const best = Number(localStorage.getItem("prepai-best-score") || 0);
  const score = Number(localStorage.getItem("prepai-last-score") || 0);
  const tasks = JSON.parse(localStorage.getItem("prepai-tasks") || "[]");
  const answers = JSON.parse(localStorage.getItem("prepai-last-answers") || "{}");
  const ids = JSON.parse(localStorage.getItem("prepai-last-question-ids") || "[]");
  const topicData = ["React", "JavaScript", "HTML", "CSS"].map((topic) => {
    const topicQuestions = questions.filter((q) => q.topic === topic && ids.includes(q.id));
    const right = topicQuestions.filter((q) => answers[q.id] === q.answer).length;
    return { topic, score: topicQuestions.length ? Math.round(right / topicQuestions.length * 100) : 0, count: topicQuestions.length };
  });
  const chart = [{ day: "Mon", score: 20 }, { day: "Tue", score: 32 }, { day: "Wed", score: 28 }, { day: "Thu", score: 48 }, { day: "Fri", score: 43 }, { day: "Sat", score: 64 }, { day: "Sun", score: score || 72 }];
  const pieData = [{ name: "Completed", value: tasks.filter((t) => t.done).length }, { name: "Remaining", value: Math.max(1, tasks.filter((t) => !t.done).length) }];
  return <div className="page-stack"><section className="page-intro"><div><span className="eyebrow"><TrendingUp size={14} /> YOUR GROWTH</span><h2>Progress that adds up</h2><p>Focus on consistency, not perfection.</p></div><Link to="/mock-interview" className="button button-primary">Practice now <ArrowRight size={16} /></Link></section><section className="stats-grid"><article className="stat-card"><div className="stat-icon violet"><Target size={20} /></div><div className="stat-copy"><span className="stat-label">Sessions completed</span><strong className="stat-value">{completed}</strong><span className="stat-note">Practice adds up</span></div></article><article className="stat-card"><div className="stat-icon amber"><Trophy size={20} /></div><div className="stat-copy"><span className="stat-label">Personal best</span><strong className="stat-value">{best}%</strong><span className="stat-note">Highest saved score</span></div></article><article className="stat-card"><div className="stat-icon blue"><BookOpen size={20} /></div><div className="stat-copy"><span className="stat-label">Study tasks</span><strong className="stat-value">{tasks.filter((t) => t.done).length}/{tasks.length}</strong><span className="stat-note">Completed tasks</span></div></article><article className="stat-card"><div className="stat-icon green"><TrendingUp size={20} /></div><div className="stat-copy"><span className="stat-label">Latest score</span><strong className="stat-value">{score}%</strong><span className="stat-note">Latest mock interview</span></div></article></section><section className="dashboard-grid"><article className="panel chart-panel"><div className="panel-heading"><div><h3>Weekly trend</h3><p>Illustrative weekly view with your latest score</p></div></div><div className="chart-wrap progress-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{ top: 8, right: 10, left: -20, bottom: 0 }}><defs><linearGradient id="progressFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8B5CF6" stopOpacity={0.24} /><stop offset="100%" stopColor="#8B5CF6" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="var(--chart-grid)" /><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tick={{ fill: "var(--muted)", fontSize: 11 }} /><Tooltip contentStyle={{ background: "var(--panel)", border: "1px solid var(--border)", borderRadius: 12 }} /><Area type="monotone" dataKey="score" stroke="#8B5CF6" strokeWidth={3} fill="url(#progressFill)" /></AreaChart></ResponsiveContainer></div></article><article className="panel readiness-panel"><div className="panel-heading"><div><h3>Study task balance</h3><p>From your personal planner</p></div></div><div className="task-donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pieData} dataKey="value" nameKey="name" innerRadius={60} outerRadius={83} paddingAngle={5} stroke="none"><Cell fill="#8B5CF6" /><Cell fill="var(--chart-grid)" /></Pie><Tooltip /></PieChart></ResponsiveContainer><div className="donut-center"><strong>{tasks.length ? Math.round(tasks.filter((t) => t.done).length / tasks.length * 100) : 0}%</strong><span>completed</span></div></div><div className="readiness-list"><div><span><i className="readiness-dot purple" /> Completed</span><strong>{tasks.filter((t) => t.done).length}</strong></div><div><span><i className="readiness-dot gray" /> Remaining</span><strong>{tasks.filter((t) => !t.done).length}</strong></div></div></article></section><section className="panel topic-progress"><div className="panel-heading"><div><h3>Topic performance</h3><p>Based on your latest saved mock interview answers</p></div></div>{topicData.map((t) => <div className="topic-progress-row" key={t.topic}><div><strong>{t.topic}</strong><span>{t.count ? `${t.count} questions attempted` : "No recent attempts"}</span></div><div className="progress-track"><i style={{ width: `${t.score}%` }} /></div><strong className="topic-percent">{t.count ? `${t.score}%` : "—"}</strong></div>)}</section></div>;
}
